/// The restrictions of a phase in a version, or `None` when that phase
/// cannot be written in that version.
pub fn restrictions(
    version: Version,
    phase: Phase,
) -> Option<&'static [(&'static str, Restriction)]> {
    match (version, phase) {
        (Version::V32, Phase::X80) => Some(V32_X80),
        (Version::V32, Phase::X81) => Some(V32_X81),
        (Version::V32, Phase::X82) => Some(V32_X82),
        (Version::V32, Phase::X83) => Some(V32_X83),
        (Version::V32, Phase::X84) => Some(V32_X84),
        (Version::V32, Phase::X85) => Some(V32_X85),
        (Version::V32, Phase::X86) => Some(V32_X86),
        (Version::V32, Phase::X87) => Some(V32_X87),
        (Version::V33, Phase::X31) => Some(V33_X31),
        (Version::V33, Phase::X50_1) => Some(V33_X50_1),
        (Version::V33, Phase::X50_2) => Some(V33_X50_2),
        (Version::V33, Phase::X51_1) => Some(V33_X51_1),
        (Version::V33, Phase::X51_2) => Some(V33_X51_2),
        (Version::V33, Phase::X52) => Some(V33_X52),
        (Version::V33, Phase::X80) => Some(V33_X80),
        (Version::V33, Phase::X81) => Some(V33_X81),
        (Version::V33, Phase::X82) => Some(V33_X82),
        (Version::V33, Phase::X83) => Some(V33_X83),
        (Version::V33, Phase::X83Z) => Some(V33_X83Z),
        (Version::V33, Phase::X84) => Some(V33_X84),
        (Version::V33, Phase::X84Z) => Some(V33_X84Z),
        (Version::V33, Phase::X85) => Some(V33_X85),
        (Version::V33, Phase::X86) => Some(V33_X86),
        (Version::V33, Phase::X86ZE) => Some(V33_X86ZE),
        (Version::V33, Phase::X86ZR) => Some(V33_X86ZR),
        (Version::V33, Phase::X87) => Some(V33_X87),
        (Version::V33, Phase::X89) => Some(V33_X89),
        (Version::V33, Phase::X89B) => Some(V33_X89B),
        (Version::V33, Phase::X93) => Some(V33_X93),
        (Version::V33, Phase::X94) => Some(V33_X94),
        (Version::V33, Phase::X96) => Some(V33_X96),
        (Version::V33, Phase::X97) => Some(V33_X97),
        (Version::V33, Phase::X98) => Some(V33_X98),
        (Version::V33, Phase::X99) => Some(V33_X99),
        _ => None,
    }
}

/// What the library itself requires of every type in a version, before
/// any phase narrows it.
pub fn base_restrictions(version: Version) -> Option<&'static [(&'static str, Restriction)]> {
    match version {
        Version::V32 => Some(BASE_V32),
        Version::V33 => Some(BASE_V33),
        _ => None,
    }
}
